"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster, mq } from "./tokens.stylex";
import { rs } from "./rs";

import { Dialog } from "./dialog";

export interface CommandItem {
  label: string;
  hint?: React.ReactNode;
  keywords?: string;
  onSelect?: () => void;
}

export interface CommandGroup {
  label?: string;
  items: CommandItem[];
}

export interface CommandProps extends React.HTMLAttributes<HTMLDivElement> {
  groups: CommandGroup[];
  placeholder?: string;
  emptyLabel?: React.ReactNode;
  onDone?: () => void;
}

const styles = stylex.create({
  palette: {
    width: {
      default: 480,
      [mq.phone]: "100%",
    },
    maxWidth: {
      default: "90vw",
      [mq.phone]: "100%",
    },
    padding: 0,
    overflow: "hidden",
  },
  input: {
    boxSizing: "border-box",
    width: "100%",
    borderWidth: 0,
    borderBottomWidth: raster.hairline,
    borderStyle: "solid",
    borderColor: raster.divider,
    backgroundColor: "transparent",
    fontFamily: "inherit",
    fontSize: {
      default: 14,
      [mq.phone]: 16,
    },
    letterSpacing: "-0.01em",
    color: raster.ink,
    paddingBlock: 14,
    paddingInline: 16,
    /* The palette clips at its edge, so the ring sits inside the field. */
    outlineWidth: {
      default: 0,
      ":focus-visible": 2,
    },
    outlineStyle: {
      default: "none",
      ":focus-visible": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible": raster.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible": -2,
    },
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
    "::placeholder": {
      color: raster.gray,
    },
  },
  list: {
    maxHeight: 320,
    overflowY: "auto",
    padding: 6,
  },
  group: {
    fontSize: {
      default: 11,
      [mq.phone]: 13,
    },
    fontWeight: 600,
    letterSpacing: "-0.01em",
    color: raster.gray,
    paddingTop: {
      default: 8,
      [mq.phone]: 12,
    },
    paddingRight: {
      default: 10,
      [mq.phone]: 14,
    },
    paddingBottom: {
      default: 4,
      [mq.phone]: 6,
    },
    paddingLeft: {
      default: 10,
      [mq.phone]: 14,
    },
  },
  item: {
    boxSizing: "border-box",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    gap: 12,
    width: "100%",
    textAlign: "left",
    borderWidth: 0,
    backgroundColor: "transparent",
    fontFamily: "inherit",
    fontSize: {
      default: 13.5,
      [mq.phone]: raster.controlFs,
    },
    letterSpacing: "-0.01em",
    color: raster.ink,
    paddingBlock: {
      default: 8,
      [mq.phone]: 12,
    },
    paddingInline: {
      default: 10,
      [mq.phone]: 14,
    },
    borderRadius: {
      default: raster.radiusSm,
      [mq.phone]: 0,
    },
    cursor: "pointer",
    minHeight: {
      default: null,
      [mq.phone]: raster.hit,
    },
  },
  itemActive: {
    backgroundColor: raster.dividerSubtle,
  },
  hint: {
    fontSize: 11,
    color: raster.gray,
  },
  empty: {
    padding: {
      default: 20,
      [mq.phone]: 24,
    },
    textAlign: "center",
    fontSize: {
      default: 13,
      [mq.phone]: 15,
    },
    color: raster.gray,
  },
});

const PAGE = 10;

/** Filter, arrows, enter. The input keeps focus; the list is aria-activedescendant. */
export function Command({
  groups,
  placeholder = "Type a command or search…",
  emptyLabel = "Nothing found.",
  onDone,
  className,
  style,
  ...props
}: CommandProps) {
  const idBase = React.useId();
  const inputId = `${idBase}-input`;
  const listboxId = `${idBase}-listbox`;
  const optionId = (index: number) => `${idBase}-opt-${index}`;
  const activeRef = React.useRef<HTMLDivElement>(null);
  const [query, setQuery] = React.useState("");
  const [activeIndex, setActiveIndex] = React.useState(0);

  const q = query.trim().toLowerCase();
  const filtered = groups
    .map((group) => ({
      ...group,
      items: group.items.filter(
        (item) => item.label.toLowerCase().includes(q) || item.keywords?.toLowerCase().includes(q),
      ),
    }))
    .filter((group) => group.items.length > 0);
  const flat = filtered.flatMap((group) => group.items);
  const hasList = flat.length > 0;

  React.useEffect(() => {
    setActiveIndex((i) => Math.max(0, Math.min(flat.length - 1, i)));
  }, [flat.length]);

  React.useEffect(() => {
    activeRef.current?.scrollIntoView?.({ block: "nearest" });
  }, [activeIndex, q]);

  const run = (item: CommandItem) => {
    onDone?.();
    item.onSelect?.();
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    const last = Math.max(0, flat.length - 1);
    switch (e.key) {
      case "ArrowDown":
        e.preventDefault();
        setActiveIndex((i) => Math.min(last, i + 1));
        return;
      case "ArrowUp":
        e.preventDefault();
        setActiveIndex((i) => Math.max(0, i - 1));
        return;
      case "Home":
        e.preventDefault();
        setActiveIndex(0);
        return;
      case "End":
        e.preventDefault();
        setActiveIndex(last);
        return;
      case "PageUp":
        e.preventDefault();
        setActiveIndex((i) => Math.max(0, i - PAGE));
        return;
      case "PageDown":
        e.preventDefault();
        setActiveIndex((i) => Math.min(last, i + PAGE));
        return;
      case "Enter": {
        e.preventDefault();
        const item = flat[activeIndex];
        if (item) run(item);
        return;
      }
      case "Escape":
        e.preventDefault();
        onDone?.();
        return;
      default:
        return;
    }
  };

  const input = rs(["rs-command-input"], styles.input);
  const list = rs(["rs-command-list"], styles.list);
  const empty = rs(["rs-command-empty"], styles.empty);
  const groupSx = rs(["rs-command-group"], styles.group);
  const hint = rs(["rs-command-hint"], styles.hint);

  let cursor = -1;
  return (
    <div className={className} style={style} {...props}>
      <input
        id={inputId}
        className={input.className}
        style={input.style}
        autoFocus
        type="text"
        autoComplete="off"
        placeholder={placeholder}
        role="combobox"
        aria-expanded={hasList}
        aria-controls={hasList ? listboxId : undefined}
        aria-activedescendant={hasList && flat[activeIndex] ? optionId(activeIndex) : undefined}
        aria-autocomplete="list"
        aria-label="Command"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setActiveIndex(0);
        }}
        onKeyDown={onKeyDown}
      />
      <div
        id={hasList ? listboxId : undefined}
        role={hasList ? "listbox" : undefined}
        aria-labelledby={hasList ? inputId : undefined}
        tabIndex={-1}
        className={list.className}
        style={list.style}
        onMouseDown={(e) => e.preventDefault()}
      >
        {flat.length === 0 && (
          <div className={empty.className} style={empty.style}>
            {emptyLabel}
          </div>
        )}
        {filtered.map((group, gi) => {
          const groupLabelId = `${idBase}-group-${gi}`;
          return (
            <div key={gi} role="group" aria-labelledby={group.label ? groupLabelId : undefined}>
              {group.label && (
                <div id={groupLabelId} role="presentation" className={groupSx.className} style={groupSx.style}>
                  {group.label}
                </div>
              )}
              {group.items.map((item) => {
                cursor++;
                const index = cursor;
                const active = index === activeIndex;
                const row = rs(
                  ["rs-command-item", active && "rs-command-item-active"],
                  styles.item,
                  active && styles.itemActive,
                );
                return (
                  <div
                    key={`${gi}-${item.label}`}
                    id={optionId(index)}
                    ref={active ? activeRef : undefined}
                    role="option"
                    tabIndex={-1}
                    aria-selected={active}
                    className={row.className}
                    style={row.style}
                    onPointerEnter={() => setActiveIndex(index)}
                    onClick={() => run(item)}
                  >
                    <span>{item.label}</span>
                    {item.hint != null && (
                      <span className={hint.className} style={hint.style}>
                        {item.hint}
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export interface CommandDialogProps extends CommandProps {
  open: boolean;
  onClose?: () => void;
}

/** The palette in a native <dialog>. Wire ⌘K in your app to setOpen(true). */
export function CommandDialog({ open, onClose, className, ...props }: CommandDialogProps) {
  return (
    <Dialog
      open={open}
      onClose={onClose}
      className={["rs-command", "rs-command-dialog", className].filter(Boolean).join(" ")}
      extraStyles={[styles.palette]}
    >
      {open && <Command onDone={onClose} {...props} />}
    </Dialog>
  );
}
